-- MSUF Suite: Traditional Chinese (zhTW) text for the Suite's English UI strings.
-- Maintained with tools/suite_locale_tool.py (missing / apply / verify);
-- one T(english, translation) line per string, sorted by the English text.
local MSUF = _G.MSUF_NS or _G.MSUF
if not MSUF or MSUF.LOCALE ~= "zhTW" then return end
local L = MSUF.RegisterLocale and MSUF.RegisterLocale("zhTW") or MSUF.L
if type(L) ~= "table" then return end
-- Keep MSUF's translated wording; replace absent or English fallback entries.
local function T(english, text)
    local current = rawget(L, english)
    if current == nil or current == english then L[english] = text end
end

