T("A channel plays a sound kit ID or a sound file (the file wins) for new messages. A burst plays once. Whisper is under Chat tools.", "頻道收到新訊息時播放指定音效組或音效檔案（優先使用檔案）。連續訊息只播放一次。密語設定位於聊天工具。")
T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "暫離時以你的角色顯示Suite電影畫面。移動或使用/afk即可返回。")
T("A class in your group can provide this buff.", "隊伍中的某個職業可以提供此增益。")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "獨立框架中的簡潔小地圖：大小、形狀、邊框、縮放、暴雪按鈕、插件按鈕抽屜與資訊文字。暴雪的小地圖按鈕仍可正常使用。")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "每個暴雪聊天視窗後方都有一塊可點擊穿透的底板。暴雪與MSUF編輯模式仍保有一般的移動與調整大小控制。")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "地圖及其邊框後方有一塊彩色底板。內邊距可將它延伸到地圖邊緣之外。")
T("A compact clock, FPS and latency bar.", "精簡顯示時間、幀率和延遲。")
T("A compact, movable history of your recent successful spells.", "一份關於你最近成功法術的緊湊、可移動的歷史記錄。")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "幀數顯示可以放在屬性條下方或單獨放置，在 MSUF 編輯模式中擺放。MSUF Suite 的 FPS 按鍵可在本次工作階段中顯示或隱藏它，戰鬥中也可用；在這裡做出新選擇會取代該工作階段開關。")
T("A group member died", "一名隊友死亡")
T("A movable strip for critical strike, haste, mastery and versatility.", "顯示致命一擊、加速、精通與臨機應變的可移動精簡資訊列。")
T("A movable summary after a Mythic+ run or raid boss kill.", "在傳奇鑰石挑戰或團隊首領擊殺後顯示可移動的摘要。")
T("A name cannot contain the | character.", "名稱不能包含 | 字元。")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "滑鼠指標周圍醒目的圓環，可選擇以共用冷卻或施法進度填滿。")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "在滑鼠指標周圍顯示圓環，方便找到指標。可選擇形狀、大小、顏色、短拖尾和中心圓點；「無圓環」只保留圓點或進度填充。鏡頭模式僅在你於遊戲世界中按住滑鼠鍵轉動鏡頭時顯示圓環、圓點和拖尾。高亮只在有內容顯示時跟隨指標，指標靜止時不會移動任何東西。")
T("A secure fishing key with optional rod, lure and a temporary sound profile.\nSet Fishing and Apply fishing lure under Keybindings > MSUF Suite.\nEach action requires your key press; interacting with the bobber stays manual.", "安全釣魚按鍵，可選用魚竿、魚餌和臨時音效設定。\n在按鍵綁定 > MSUF Suite中設定釣魚和使用釣魚魚餌。\n每個操作均需按鍵，仍須手動與浮標互動。")
T("A sequence uses one condition rule", "序列僅使用一條條件規則")
T("A small panel beside the Group Finder search results. Its Search filters button saves your difficulty, minimum leader rating, role and dungeon choices in Blizzard's advanced search filter for your next manual search. Use Blizzard's Search button to search. It works on dungeon searches at maximum level, outside combat, and signs you up for nothing.", "在預組隊伍搜尋結果旁顯示小面板。「搜尋篩選」按鈕會將難度、隊長最低評分、角色職責和地城選項儲存至暴雪進階篩選，供下次手動搜尋使用。請點擊暴雪的「搜尋」按鈕開始搜尋。僅在滿級、非戰鬥狀態的地城搜尋中生效，不會自動申請隊伍。")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "一個小摘要位於角色面板的角色分頁旁，並隨其一同隱藏。它列出帶寶石插槽的裝備及已鑲嵌數量，空插槽以琥珀色顯示（點擊一行開啟鑲嵌），裝備的總耐久度，以及可選的PvP物品等級。其按鈕可開啟宏偉寶庫和目前資料片頁面。面板開啟時更新，每幀最多一次。")
T("A snapshot of current keys and loaded Suite action bars. Refresh after changing actions, forms or bindings.", "目前按鍵和已載入的Suite快捷列快照。變更動作、形態或按鍵後請重新整理。")
T("A soft light behind the map, independent of the border and artwork.", "地圖後方的柔和光暈，與邊框和裝飾圖無關。")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "包含寶石插槽、耐久度、PvP物品等級以及宏偉寶庫和資料片按鈕的摘要，模型上的耐久度，裁切的裝備欄圖示，以及裝備選擇中的物品等級。")
