T("Adds automatic collection on top of Blizzard's own Auto Loot setting, which stays unchanged. Locked slots and confirmations stay manual.", "在暴雪自身的自動拾取設定之外額外加入自動拾取，原設定保持不變。已鎖定的欄位與確認視窗仍須手動處理。")
T("Adds every spell of this group that you know. Spells on another bar move here.", "新增此組中你已學會的所有法術。位於其他條列上的法術會移至這裡。")
T("Adds guild rank, the hovered unit's target, item levels, the unit's current mount and item or spell details to Blizzard's main tooltip, and can show player names without titles. Your own item level and the one of the unit open in the Inspect window need no request. Item levels of other hovered players are a separate choice that sends inspect requests: at most one per hover, never while the Inspect window or another inspect is busy. Mounts are read once when a unit tooltip opens, out of combat; a change appears on the next hover. Place the fixed corner in MSUF Edit Mode; the cursor offsets apply to the cursor anchor.", "為暴雪主要滑鼠提示加入公會階級、單位的目標、物品等級、單位目前的坐騎以及物品或法術詳細資訊，並可顯示不含頭銜的玩家名稱。你自己的物品等級與觀察視窗中已開啟單位的物品等級無需請求。滑鼠所指其他玩家的物品等級是獨立選項，會傳送觀察請求：每次停留最多一次，觀察視窗或其他觀察正在進行時絕不傳送。坐騎會在戰鬥外開啟單位提示時讀取一次；更換後的坐騎會在下次停留時顯示。固定角落在 MSUF 編輯模式中放置；游標偏移用於游標錨點。")
T("Adds the current-season Mythic+ score to the main tooltip of another player when Blizzard provides a public score. Unknown or restricted scores stay hidden.", "當暴雪提供公開分數時，將當前賽季的 Mythic+ 分數添加到其他玩家的主要工具提示中。未知或受限的分數保持隱藏。")
