T("Blizzard keeps 128 lines in each window. A higher limit lets you scroll back further and lets saved history fill the window.", "暴雪每個視窗保留 128 行。提高上限可回看更早內容，並允許儲存的聊天記錄填入視窗。")
T("Blizzard keeps every original font size and style flag.", "暴雪保留所有原始字型大小與樣式標記。")
T("Blizzard keeps its text sizes and outlines.", "暴雪保留其文字大小與外框。")
T("Blizzard keeps the button artwork, clicks, tooltips, enabled states and notifications. Optional glyph artwork is available in the detail controls. Visual changes apply outside combat only.", "按鈕圖案、點擊、滑鼠提示、啟用狀態與通知仍由暴雪保留。可在細節設定中選用符號圖案。視覺變更僅在非戰鬥時生效。")
T("Blizzard layout captured", "已擷取暴雪版面")
T("Blizzard layout imported", "已匯入暴雪版面")
T("Blizzard original", "暴雪原版")
T("Blizzard owns aggro flashes, progressive highlights and soft target icons. Optional colors tint Blizzard's existing threat textures; its health bar threat color stays under the role-color overlay. Soft target icons also need the nameplate icon switch enabled and a matching soft target in game.", "仇恨閃爍、漸進醒目效果與軟目標圖示由暴雪管理。可選顏色用於著色現有威脅材質；血條的威脅顏色仍在角色職責色彩覆蓋層下方。軟目標圖示還需要啟用名條圖示開關，並在遊戲中存在符合的軟目標。")
T("Blizzard owns the aura icons and updates. Choose Keep Blizzard setting or Customize for each unit type. Buffs, debuffs and control effects can be selected and dragged separately in the preview. Aura size uses Blizzard's own setting.", "光環圖示與更新由暴雪負責。為每種單位類型選擇「保留暴雪設定」或「自訂」。增益、減益與控場效果可在預覽中分別選取與拖曳。光環大小採用暴雪自身的設定。")
T("Blizzard owns these elements. The rarity icon setting applies to all nameplates; raid target icons are hidden only on enemy plates. Castbar details control Blizzard's own castbar. The preview and live plates use the same switches.", "這些元素由暴雪負責。稀有度圖示設定套用到所有名條；團隊目標圖示只在敵方名條上隱藏。施法條細節控制暴雪自己的施法條。預覽與實際名條使用相同的開關。")
T("Blizzard personal auras", "暴雪個人光環")
T("Blizzard plate size (health bar + elements)", "暴雪名條大小（生命條+元素）")
T("Blizzard plate style", "暴雪名條風格")
T("Blizzard plates", "暴雪名條")
T("Blizzard player auras", "暴雪玩家光環")
T("Blizzard portrait", "暴雪頭像")
T("Blizzard raid target icon on enemy plates", "敵方名條的暴雪團隊目標圖示")
T("Blizzard setting", "暴雪設定")
T("Blizzard shield", "暴雪盾牌")
T("Blizzard spell icon", "暴雪法術圖示")
T("Blizzard supplies health and aura updates. List edits and preview work during combat; color pickers work after combat.", "暴雪提供生命值和光環更新。戰鬥中可編輯清單並預覽；顏色選擇在戰鬥結束後可用。")
T("Blizzard supplies the castbar texture, colors, progress and interrupts. Customize its text and details here. Select and move each cast element in the preview; positions apply outside combat.", "施法條的材質、顏色、進度與中斷由暴雪提供。可在此自訂其文字與細節。在預覽中選取並移動每個施法元素；位置會在非戰鬥時套用。")
T("Blizzard supplies the icons. The Suite keeps its own button plates, bar frame and spacing. Native clicks, tooltips and notifications stay intact.", "圖示由暴雪提供。Suite保留自己的按鈕底板、條框架與間距。原生點擊、滑鼠提示與通知維持不變。")
T("Blizzard supplies the name and health values. Mapko requests full enemy plates and both health values so normal enemies show text too. Width and height change only the enemy health bar in pixels; 0 keeps the selected bar dimensions. Backdrop, border and role fill are separate live skin layers in the preview; right-click a layer for its setting. Role colors use the saved palette; mana is only a caster hint. Open the three-dot menu here or Nameplates in MSUF Colors to change the palette.", "名稱與生命值由暴雪提供。Mapko要求完整敵方名條及兩種生命值，使一般敵人也顯示文字。寬度與高度只更改敵方血條的像素尺寸；0保留所選尺寸。預覽中的背景、邊框與職責填色是獨立的即時外觀層；右鍵點擊某一層可開啟對應設定。職責顏色使用已儲存的調色盤；法力僅作為施法者提示。可在此處的三點選單或MSUF色彩中的名條頁面更改調色盤。")
