T("Blizzard's own buttons stay functional. The row is their starting position; drag each icon freely in the preview.", "暴雪自己的按鈕仍可正常使用。此列是它們的起始位置；可在預覽中自由拖曳每個圖示。")
T("Blizzard's own cooldown swipe fills the ring: the global cooldown after each ability, and casts or channels while they run. A cast takes the place of the global cooldown until it ends; the bright edge marks how far the cast has come.", "暴雪自己的冷卻掃過動畫填充圓環：每個技能後的共用冷卻，以及正在進行的施法或引導。施法期間會取代共用冷卻直到結束；明亮的邊緣標出施法進度。")
