T("Bubbles outside instances can take the MSUF look; Blizzard locks the ones inside instances. Each source keeps Blizzard's look or uses the MSUF one: the shared look or its own font, size, colors, spacing and width. A bubble is matched to the line it shows right after that line arrives. Turning bubbles off inside instances uses Blizzard's bubble settings and gives them back when you leave or turn it off.", "副本外的聊天泡泡可以使用 MSUF 外觀；副本內的泡泡由暴雪鎖定。每個來源可以保留暴雪外觀，或使用 MSUF 外觀：共用外觀，或獨立的字型、大小、顏色、間距和寬度。一則訊息到達後，泡泡會立即與其顯示的文字對應。在副本內關閉泡泡會使用暴雪的泡泡設定，離開副本或關閉此選項時會恢復原設定。")
