T("Choose Categories for \"Default inventory view\" or Bank categories for \"Default bank view\".", "請將「預設背包檢視」設為「分類」，或將「預設銀行檢視」設為「銀行分類」。")
T("Choose Categories for \"Default inventory view\".", "請將「預設背包檢視」設為「分類」。")
T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "為美化與已啟用的Suite模組選擇簡潔現代、Midnight Blue、MSUF Forever玻璃、Midnight Dark或職業風格。之後啟用的模組也會沿用。")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "選擇簡潔現代、Midnight Blue、Midnight Dark、MSUF Forever或職業風格。僅更改背包視窗的顏色與透明度；物品欄位及暴雪背包操作保持不變。")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "可選擇 Clean Modern、Midnight Blue、中性的 Midnight Dark 玻璃風格，或 MSUF Forever 的深金色邊框。所有風格都使用 MSUF 的狀態條材質和字體。可開關經驗條的 20 段分隔線。下方一行可顯示本次登入獲得的經驗、每小時經驗和預計升級時間。在 MSUF 編輯模式中移動或調整經驗條；彈出視窗可設定 X、Y、寬、高和縮放。滑鼠懸停可查看精確數值。工作階段資料在 /reload 後保留，下次登入重新開始。")
T("Choose Craft quantity to change how many times you plan to craft this tracked recipe.", "選擇製作數量，修改該追蹤配方的預計製作次數。")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "選擇「自訂」版面以設定總量、每秒與百分比數值的順序，再選擇空格、括號或分隔符號。百分比開關控制主要列；明細列會顯示可用的佔比。無法取得的佔比會省略。「主要」對DPS/HPS表示每秒數值，對其他統計則表示總量。文字設定也會套用到標題、細節與浮動計時器。Slug使用WoW清晰的字型渲染器，帶外框且無陰影。受保護的數值在戰鬥結束前不顯示百分比。")
T("Choose DoTs for this specialization. Disabled entries keep their position.", "為此專精選擇持續傷害。停用的項目保留原有位置。")
