T("Choose a preset below or fine-tune with the slider.", "在下方選擇預設，或用滑桿微調。")
T("Choose a profile that exists in both parts of the suite", "選擇在Suite兩部分中都存在的設定檔")
T("Choose a random owned Hearthstone variant for the next click", "下次點擊隨機選擇已擁有的爐石變體")
T("Choose a smaller stack size and make sure the item is unlocked, your cursor is empty and you are out of combat.", "請選擇較小的堆疊數量，並確保物品未鎖定、游標未持有物品且已脫離戰鬥。")
T("Choose a sound", "選擇音效")
T("Choose a spell or item", "請選擇法術或物品")
T("Choose a spell to inspect its shared or specialization settings.", "選擇法術以查看共用或專精設定。")
T("Choose a spell, item or value", "請選擇法術、物品或數值")
T("Choose a starting point. Existing bars stay unchanged.", "選擇一個起始方案，現有資訊列保持不變。")
T("Choose a style above or change these colors to make a Custom look. Rows update immediately.", "選擇上面的樣式或變更這些顏色以形成自訂外觀。行立即更新。")
T("Choose a style, font and coverage in minutes. Every deeper control remains available in Expert mode.", "幾分鐘內即可選好風格、字型與套用範圍。所有更深入的控制都保留在專家模式中。")
T("Choose a style, then adjust its thickness in Bars or Window and header.", "選擇樣式後，在條形或視窗與標題列中調整粗細。")
T("Choose a tab, search and select an entry for details.", "選擇分頁，搜尋並選取項目以檢視詳情。")
T("Choose a template", "選擇模板")
T("Choose a valid fishing rod.", "請選擇有效的魚竿。")
T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "選擇MSUF字型、外框、陰影，以及平滑、銳利或Slug渲染。Slug沒有陰影。標籤、數值與警告顏色分開設定。")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "選擇MSUF或SharedMedia的字型與條材質。字型大小、外框、陰影、平滑/銳利/Slug渲染、條高度與間距會立即更新HUD。Slug沒有陰影。")
T("Choose an item", "選擇物品")
T("Choose at least one DoT to enable aura colors", "至少選擇一個持續傷害以啟用光環顏色")
T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "選擇大範圍的介面類別。專用的安全行為與具意義的圖案維持不變。")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "為每個位置選擇資料來源名稱和已發現的貨幣 ID。從原生貨幣清單中選擇目前賽季的紋章貨幣；儲存的貨幣選擇在登入後即可使用，無須拜訪升級 NPC。選擇順序和分隔符控制紋章區塊。本次登入期間選擇升級物品後，仍可改用已觀察到的升級階段。爐石操作需要主動點擊。")
T("Choose buffs and consumables to track.", "選擇要追蹤的增益和消耗品。")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "選擇簡潔的視窗按鈕與完整的微型選單列風格，僅在需要時再調整個別圖案。")
T("Choose coverage", "選擇套用範圍")
T("Choose crest currencies", "選擇紋章貨幣")
T("Choose currencies", "選擇貨幣")
T("Choose data", "選擇資訊")
T("Choose data for place %d", "選擇位置%d的資料")
T("Choose data source", "選擇資訊來源")
T("Choose discovered currency", "選擇已發現的貨幣")
T("Choose dungeon", "選擇地城")
T("Choose dungeon portals", "選擇地城傳送")
T("Choose dungeons", "選擇地城")
T("Choose each Blizzard popup separately. The feature hides its window when it appears and leaves the underlying game events intact. Combat lockdown can prevent hiding a protected window.", "可分別選擇要隱藏的暴雪彈出視窗。視窗出現時只隱藏視窗，遊戲事件仍正常觸發。戰鬥限制可能使受保護的視窗無法隱藏。")
T("Choose fishing rod from bags", "從背包選擇魚竿")
T("Choose icon", "選擇圖示")
T("Choose individual recurring UI errors to hide with Blizzard's own message filter.", "選擇個別重複出現的 UI 錯誤以使用暴雪自己的訊息過濾器進行隱藏。")
T("Choose item", "選擇物品")
T("Choose loaded broker", "選擇已載入的 Broker 插件")
T("Choose lure from bag consumables", "從背包消耗品中選擇魚餌")
T("Choose material", "選擇材料")
T("Choose modules", "選擇模組")
T("Choose observed seasonal stages", "選擇已觀察的賽季階級")
T("Choose one font for Blizzard UI text. Existing sizes, outlines, shadows and accessibility scaling are preserved.", "為暴雪介面文字選擇一種字型。現有的大小、外框、陰影與協助工具縮放都會保留。")
T("Choose one material alternative before this slot can enter the total.", "請先選擇該欄位使用的材料，再將其計入總量。")
T("Choose one target per rule", "每條規則請選擇一個目標")
T("Choose preview DoTs", "選擇預覽持續傷害")
T("Choose supplies from bags", "從背包選擇補給品")
T("Choose the detailed character view and its extra information. Changing the view reloads the UI.", "選擇詳細的角色檢視及其額外資訊。變更檢視會重新載入介面。")
T("Choose the dungeon difficulties where MSUF starts the combat log. Mythic+ begins when the keystone starts.", "選擇MSUF要開始戰鬥記錄的地城難度。傳奇+會在鑰石啟動時開始。")
T("Choose the map shape, then adjust its border and outer shadow.", "選擇地圖形狀，再調整其邊框與外陰影。")
T("Choose the raid difficulties where MSUF starts the combat log.", "選擇MSUF要開始戰鬥記錄的團隊副本難度。")
T("Choose the shared button colors and frame. Layout, bindings and visibility stay as set. Changing an individual color switches the label to Custom.", "選擇共用的按鈕顏色與框架。版面、按鍵綁定與可見性保持原設定。變更個別顏色會將標籤切換為「自訂」。")
T("Choose the values shown on each bar.", "選擇每條計量條上顯示的數值。")
T("Choose this character's class and specialization above.", "請在上方選擇此角色的職業和專精。")
T("Choose this item to add it to your list.", "選擇此物品以加入清單。")
T("Choose volumes for each activity. Turning this off restores the previous volumes when they are still owned by MSUF.", "為每種活動設定音量。關閉後，將還原仍由MSUF控制的先前音量。")
T("Choose what the Suite tracker lists and when it steps aside.", "選擇 Suite 追蹤器顯示的內容以及何時讓位。")
T("Choose where recent actions appear. Delves have their own switch; battlegrounds and arenas share one, and other scenarios follow Outside instances. Where the tracker is switched off, it does not listen to your casts.", "選擇最近動作顯示的位置。探究有獨立的開關；戰場和競技場共用一個，其他事件跟隨「副本外」。在關閉的地方，它不會監聽你的施法。")
T("Choose whether the Time place shows the realm clock or your computer's clock, in 12 or 24 hours, with or without seconds.", "選擇時間資訊區塊顯示伺服器時間還是電腦時間，以及 12/24 小時制和是否顯示秒數。")
T("Choose which Blizzard interfaces receive the skin. Blizzard keeps their interactions.", "選擇要套用美化的暴雪介面。互動仍由暴雪處理。")
T("Choose which learned portals the minimap flyout and the DataText portal and travel menus list: all of them, those of the current Mythic+ season, which the game keeps up to date each season, or your own set. Learned dungeon portals use secure buttons. Group suggestions require a verified dungeon map or an exact destination match and consider every learned portal. Unknown destinations show no suggestion; buttons hide in combat.", "選擇小地圖彈出選單以及資訊文字的傳送和旅行選單要顯示哪些已學會的傳送：全部、目前傳奇鑰石賽季的傳送（遊戲每個賽季自動更新），或你自己的組合。已學會的地城傳送法術使用安全按鈕。隊伍傳送建議需要經過驗證的地城地圖或完全相符的目的地，並會考慮所有已學會的傳送。未知目的地不顯示建議；按鈕在戰鬥中隱藏。")
T("Choose your alt, subject and material quantities. Apply and attach from the Send Mail tab, then review and send manually.", "選擇自己的分身、主旨及材料數量。在寄送郵件頁套用並附加，然後檢查並手動寄送。")
T("Choose your buffs or your own harmful auras on the current target. The additional required buff is always checked on you.", "選擇自身增益或由你施加在目前目標上的有害光環。額外要求的增益一律在自身檢查。")
T("Choose your character", "選擇自己的角色")
T("Choose your lure; other consumables are also listed.", "請選擇魚餌，清單也包含其他消耗品。")
T("Choosing a look updates Skinning and every enabled Suite module. Modules enabled later inherit it. New skin profiles start with %s.", "選擇外觀會更新美化與每個已啟用的Suite模組。之後啟用的模組會沿用它。新的美化設定檔以%s開始。")
T("Cinematic confirmation can be skipped after you choose to exit. Automatic skipping is a separate option and also skips movies. Both stay inactive during combat, and a vehicle sequence always keeps its exit confirmation. Hide tutorials while this helper is enabled, prefill the DELETE word while keeping the final confirmation manual, hide only the successful screenshot notice, or open your character window at merchants on the tab you used last. At the auction house, Blizzard's filter button is marked while Current Expansion Only is off; tick it there once and Blizzard keeps it for this character.", "選擇退出後，可略過過場動畫確認。自動略過是獨立選項，也會略過影片。兩項功能在戰鬥中均不生效，載具場景一律保留離開確認。此助手還可隱藏教學、預填刪除確認詞但保留最後的手動確認、僅隱藏擷取畫面成功提示，或在商人處以上次使用的分頁開啟角色視窗。在拍賣場中，「僅限目前資料片」關閉時會標記暴雪的篩選按鈕；在那裡勾選一次，暴雪會為此角色保留。")
T("Cinematic zone and event announcements in the Suite look.", "以Suite外觀呈現的電影式區域與事件公告。")
