T("Clean Modern is the Retail default; MSUF Forever is the Forever default. Midnight Blue keeps the original blue glass. Open a section's three-dot menu to change its colors, or use MSUF Colors for the full palette. Your own color changes become Custom.", "簡潔現代是正式版預設主題；MSUF Forever是Forever預設主題。Midnight Blue保留原有藍色玻璃外觀。開啟某個區段的三點選單可更改其顏色，或在MSUF色彩中調整完整調色盤。自行修改顏色後將變為自訂。")
T("Clean Modern uses matte panels with white accents. Midnight Blue keeps the original blue palette. Midnight Dark uses neutral charcoal glass; MSUF Forever retains its muted gold. Color changes become Custom.", "簡潔現代使用帶白色點綴的霧面面板。Midnight Blue保留原有藍色調色盤。Midnight Dark使用中性炭灰色玻璃外觀；MSUF Forever保留柔和金色。修改顏色後將變為自訂。")
T("Clean Modern, Midnight Blue, Midnight Dark and MSUF Forever are complete looks in Style. Color palettes here change colors only; use Expert mode for every UI state.", "簡潔現代、Midnight Blue、Midnight Dark與MSUF Forever是「風格」中的完整外觀。這裡的調色盤只改變顏色；如需調整每種介面狀態，請使用專家模式。")
