T("Clicks pass through the window to the game. Edit Mode and the preview still use the mouse, and Mouseover windows cannot be click-through.", "點擊會穿過視窗傳遞給遊戲。編輯模式和預覽仍可使用滑鼠；滑鼠懸停顯示的視窗不能啟用點擊穿透。")
