T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "雙擊搜尋結果以開啟暴雪的申請視窗。啟用雙擊提交後，第二次點擊還會以該視窗中已選的職責直接申請；按住 Shift 則改為檢查視窗。儲存的備註可顯示在視窗旁以便複製；結束編輯時才會儲存。")
