T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "拖曳視窗頂端邊緣即可移動；拖曳右下角可縮放。右上角的減號按鈕會將相容的視窗收合成還原分頁。背包與受保護的視窗維持原生行為。")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "在MSUF編輯模式中拖曳公告，或在此設定其時機、縮放與精確位置。")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "拖曳或使用方向鍵移動；Shift：5，Ctrl：10。")
T("Drag or use arrows to move; click for settings.", "拖曳或使用方向鍵移動；點擊開啟設定。")
T("Drag the bag title to move it; click for options.", "拖曳背包標題可移動，點擊可開啟選項。")
T("Drag the bar's edge to move it on screen.", "拖曳條的邊緣即可在畫面上移動它。")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "材料背包開啟時拖曳其標題即可單獨移動。點擊標題開啟背包選項。在MSUF編輯模式中重置其位置，即可恢復暴雪的一般背包配置。")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "在MSUF編輯模式中拖曳結果卡片，或在此設定螢幕錨點、寬度、縮放與位置。")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "拖曳已開啟背包的標題即可移動。點擊標題開啟背包選項。每個背包各自保留位置。暴雪在右側顯示你目前的金錢；左側可選的「本次登入」數值顯示登入後的變化，並在/reload後保留。可在此或其MSUF編輯模式彈出視窗中調整合併背包的大小。在編輯模式中重置位置會讓視窗回到暴雪的一般錨點。")
