T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "將物品拖到分類側欄的「置頂物品」，即可在所有檢視中置頂。「最近物品」最多列出此角色獲得的200種物品，重新登入後仍會保留；每種物品超過此處設定的小時數後會移出清單，「清空最近物品」可提早清空。這些操作均不會移動或刪除物品。")
