T("Each phrase may contain up to 80 characters.", "每個詞組最多80個字元。")
T("Each response is its own switch and none acts in combat. A summon that skips a starting area, and a resurrection during a boss encounter or while Blizzard makes you wait, stay yours. Party invite declines never touch friends, Battle.net friends or guild members, and invites that ask for a role or start a quest session stay yours. A chat line can report each response.", "每種回應都有獨立開關，戰鬥中均不執行。會跳過起始區域的召喚，以及首領戰中或暴雪要求等待時的復活，均由你手動處理。不會拒絕好友、Battle.net 好友或公會成員的組隊邀請；需要選擇職責或開始任務同步工作階段的邀請也由你處理。可在聊天中提示每次回應。")
T("Each specialization keeps its own bar layout: positions, attachments, growth, rows, spacing and sizes. Until it has its own, it uses the current one.", "每個專精都會保留自己的條版面配置：位置、附著、增長方向、列數、間距與大小。尚無自己的配置時，使用目前配置。")
T("Each window keeps its own meter, fight, size and visibility rules. Drag the header or use MSUF Edit Mode to move it.", "每個視窗各自保留統計類型、戰鬥、大小與可見性規則。拖曳標題列或使用MSUF編輯模式即可移動。")
