T("Enter a spell name or ID on MSUF action bars. Its buttons glow from the aura and unit selected below. A page change in combat pauses the glow until combat ends.", "輸入 MSUF 快捷列上的法術名稱或 ID。按鈕依下方選擇的光環和單位發光。戰鬥中切換頁面會暫停發光，直到戰鬥結束。")
T("Enter a talent or spell name or ID, then press Enter. Every required spell must be learned. Empty removes this condition.", "輸入天賦或法術名稱或ID，然後按Enter。所有必要法術都必須已學會。留空可移除此條件。")
T("Enter a talent or spell name or ID, then press Enter. The entry is hidden while any excluded spell is learned. Conditions update outside combat.", "輸入天賦或法術名稱或ID，然後按Enter。只要已學會任一排除法術，就隱藏此項目。條件在脫離戰鬥時更新。")
