T("Enter the cast spell's name or ID. Leave empty for automatic spell matching. Timers start only from readable player cast events.", "輸入施放法術的名稱或ID。留空則自動配對法術。計時器僅由可讀取的玩家施法事件啟動。")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "最多輸入 200 個物品 ID。按鈕只在商人處出現，並預覽符合條件的物品堆；點擊後會開啟確認視窗。要求出售前，功能會重新檢查物品身分、品質、價值、任務狀態及背包位置。可裝備物品需要另外啟用對應選項。")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "最多輸入 8 個移動技能的法術 ID。開始移動時，會短暫顯示第一個已學會、冷卻完畢且可使用的法術。提示共用 20 秒冷卻時間，避免頻繁出現。ID 留空時不執行任何操作。可在 MSUF 編輯模式中移動提示。")
