T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "此條的所有法術，包含尚未學會的。在增益條上，「新增法術」會提供可接受的增益，例如能量灌注與啟動；「我身上的增益」也接受增益光環ID或可解析的名稱，並追蹤任何施法者施放的該ID。關閉「變暗顯示缺少的增益」時，只會顯示作用中的增益。預覽也能編輯項目：點擊開啟選項，拖曳以重新排序或拖到上方的條，中鍵移除（可復原）。已移除的法術仍列在「新增法術」下。清單依專精分別保存。")
