T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "術士只會在戰鬥中燃燒狂奔光環生效時顯示提示。暴雪內建光環容器會追蹤該光環；Suite 不掃描光環。MSUF 編輯模式可顯示範例並移動提示。")
