T("Forever factory profile unavailable", "無法使用Forever出廠設定檔")
T("Forever only. A secure fishing key that casts Fishing, equipping the rod you choose first, and a second key that applies the lure you choose. Set both under Keybindings > MSUF Suite. Each action needs your key press; interacting with the bobber stays manual. The optional sound profile sets your fishing volumes while you cast and restores them afterwards.", "僅限 Forever。安全釣魚快捷鍵會先裝備所選釣竿，再施放釣魚；另一快捷鍵用於使用所選魚餌。請在按鍵設定 > MSUF Suite 中設定。每個操作都需親自按鍵，與浮標互動仍需手動。可選音量設定檔會在施放釣魚期間套用釣魚音量，並在之後恢復。")
T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "僅限 Forever。學習並在此設定檔中儲存完整飛行路線耗時。首次飛行不虛構預估時間。提前降落不會覆蓋完整路線耗時。中途站點來自原生飛行地圖，提示可預覽路線。「在下一站降落」請求下一個可用降落點。")
T("Forever only. When a quest offers a choice of rewards, the one with the highest vendor value, counting its stack size, is marked. Nothing is selected or turned in for you.", "僅限 Forever。任務提供可選獎勵時，會標記按堆疊數量計算後售價最高的獎勵。不會替你選擇或交付任務。")
