T("Frames join aligned bars; detached bars keep separate frames. Effects are static. Threshold marks a fixed percentage. Preview switches apply live.", "外框連接生命條與施法條，沒有可見施法時僅包圍生命條。陰影和發光為靜態效果。材質保留生命和光環顏色。門檻線標記固定百分比，不是斬殺提醒。可在預覽圖層中分別開關各項功能。 位置分離或大小不同的條使用各自的邊框。")
