T("Friendly player display chooses Blizzard's setting, names for all friendly players, names for party / raid only, or health bars. Names only hides Blizzard bars, casts and auras for friendly players; it does not change NPC or enemy plates. Group / outsider in the preview only changes the sample. Blizzard can forbid changes to friendly plates in instances; those frames stay under Blizzard's control.", "「友方玩家顯示」可選擇暴雪設定、所有友方玩家顯示名稱、僅隊伍/團隊顯示名稱，或顯示生命條。「僅名稱」會隱藏友方玩家的暴雪條、施法與光環；不會變更NPC或敵方名條。預覽中的「隊伍/隊伍外」只會改變範例。暴雪可能禁止在副本中變更友方名條；這些框架仍由暴雪控制。")
