T("Gives Blizzard's player buffs and debuffs the icon skins you chose on the Icon Skins page, at Blizzard's own size and layout. The skins are painted once, out of combat, and no code runs on aura updates. While Player aura layout is on, it paints the buttons itself and this switch waits.", "將圖示外觀頁面所選的外觀套用至暴雪玩家增益和減益圖示，保留暴雪原有大小與配置。外觀僅在非戰鬥狀態繪製一次，光環更新時不執行額外程式。啟用玩家光環配置時，由該功能自行繪製按鈕，此開關暫時等待。")
