T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "可在戰鬥中、副本中，或對所選的物品、法術和單位提示隱藏暴雪主要滑鼠提示。MSUF單位和團隊框架的提示仍使用各自的可見性設定；光環提示仍由各自的顯示滑鼠提示開關控制。各選項獨立生效。被隱藏的提示會變為完全透明，暴雪仍照常處理它。")
