T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "按住Alt可在提示中查看物品、法術、生物、任務、貨幣或臨時武器附魔的ID，也可以在提示開啟時按下Alt；ID會保留到提示重新產生為止。法術圖示ID和暴雪的其他角色貨幣資料是可選的，這些資料到達時會加入開啟的提示。客戶端保持私密的ID或數量不會顯示。")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "滑鼠指向物品、法術、生物、任務、貨幣或暫時武器附魔時按住 Alt，可在主要滑鼠提示中查看 ID。")
T("Hold Midnight Artisan payouts while Shard of Dundun is capped", "敦敦裂片達到上限時保留至暗之夜工匠報酬")
T("Hold Shift to pause. Quests with a money cost and quests with a reward choice always stay manual.", "按住Shift可暫停。需花費金錢或需選擇獎勵的任務一律保持手動。")
T("Hold a key to show hidden tooltips", "按住按鍵顯示隱藏提示")
T("Hold the selected key while clicking Release Spirit. The release button stays hidden until you hold it; resurrection and death recap remain available. Choose where to use the protection. Blizzard's automatic release timer is unchanged.", "按住所選按鍵後點擊釋放靈魂。未按住該鍵時，釋放按鈕會隱藏；復活與死亡回顧仍然可用。可選擇保護生效的場合。暴雪的自動釋放計時器不會改變。")
T("Hold to release", "按住以釋放")
