T("How the icons line up and grow. A free bar's position counts from the screen center; an attached bar's is an offset from its attach point. Excess cooldowns can move past Maximum icons to another enabled cooldown bar. The destination must have overflow off; chained routes are ignored.", "圖示的排列與延伸方式。自由列的位置相對於螢幕中央；附加列的位置相對於其錨點。超過最大圖示數量的冷卻可轉移到另一個啟用的冷卻列。目標必須關閉溢出轉移；連鎖轉移將被忽略。")
