T("Inside a raid the tracker turns into an encounter view at its usual place: boss name, pull timer, the bosses engaged right now with their health, your best wipe and your fastest kill. Phases come from DBM or BigWigs when one is installed; otherwise the phase stays open. A wipe with more bosses down beats one with fewer, and with the same count the one with less boss health left wins. Each character keeps its own records. Boss health shows only while the client reveals it.", "在團隊副本中，追蹤器會在原位置變成首領戰檢視：首領名稱、開戰計時、目前交戰的首領及其生命值、你的最佳滅團與最快擊殺。安裝了 DBM 或 BigWigs 時由其提供階段，否則階段保持未知。擊敗首領較多的滅團優於較少的；數量相同時，首領剩餘生命值較少者勝出。每個角色各自保存紀錄。首領生命值只有在用戶端公開時才會顯示。")
