T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Sort items by orders every Suite view; Name keeps the order each view has always had. Click a category header to hide or show its items. The footer counts free slots, and Mark items that beat what you wear puts a small arrow on equipment that beats what you wear in its slot. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "可保留暴雪格線，或選擇 Suite 統一格線、依實體背包分組或分類。在背包視窗中使用「編輯分類」建立、重新命名、排序或停用分類；將物品拖至側欄分類即可分配。「物品排序依據」影響所有 Suite 檢視；「名稱」保留各檢視原有排序。點擊分類標題可摺疊或展開物品。底部顯示空格數，「標記優於目前裝備的物品」會在對應部位更好的裝備上顯示小箭頭。背包較大時可捲動或使用「上一頁/下一頁」；戰鬥中同時顯示全部格子。合併堆疊數量僅影響顯示；在銀行、公會銀行、郵件、交易、拍賣場和商人處均恢復實體堆疊。")
