T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "在暴雪寶石插槽視窗旁列出背包中的寶石種類。先透過正常的背包滑鼠提示查看每顆寶石，再於遊戲內建插槽視窗確認是否相容，之後才鑲嵌。")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "在五人地城中列出可攻擊敵人名條上的施法，最早的在前；每條進度條和計時由遊戲執行。遊戲會對插件隱藏法術、目標、標記和能否中斷，因此列表從不依這些資訊排序或篩選：淡化或隱藏使用遊戲的重要法術標記（隱藏的施法仍保留它在列表中的位置），團隊標記顯示在法術圖示上，中斷技能不在冷卻時，可中斷的施法會顯示就緒標記（邊緣色條或整條）。調暗功能每秒四次檢查你的中斷能否搆到列表中的每個敵人；無法檢查的施法保持明亮。除非你輸入法術ID，否則依你的天賦和寵物識別中斷技能。MSUF 編輯模式會顯示範例施法，方便放置列表。")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "在五人地城中列出敵方名條上的施法，最早的在前，計時由遊戲執行。")
