T("MSUF icons replace the scattered Blizzard chat controls. Friends, channels, text to speech and the chat menu keep their Blizzard actions; the bottom icon jumps to the newest message. Turn this off to restore the native buttons.", "MSUF圖示取代分散的暴雪聊天控制項。好友、頻道、文字轉語音與聊天選單保留其暴雪動作；底部圖示可跳到最新訊息。關閉此選項即可恢復原生按鈕。")
