T("MSUF stops only a log it started. A log that was already on stays on. Re-entering selected content cancels a pending stop. WoW writes the log in its Logs folder.", "MSUF只會停止由它開始的記錄。原本已開啟的記錄會保持開啟。重新進入所選內容會取消待執行的停止。WoW會將記錄寫入其Logs資料夾。")
