T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline 涵蓋盜賊毒藥、本季的精鍊藥劑、增強符文和武器油，以及「充分進食」食物增益。每個類別點擊時使用背包中第一個符合的物品；為其填寫的物品會優先嘗試。食物會依照遊戲的進食法術在背包中尋找：先使用你填寫的食物，然後是最新的食物。開啟灰色提醒後，用完的類別仍會顯示，但沒有點擊動作。刺殺優先致命毒藥，暴徒和敏銳優先速效毒藥。龍淬之刃允許每個類別兩種毒藥。武器油作用於已裝備的武器；已學會薩滿或聖騎士的武器附魔時不會自動提醒武器油。")
