T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko在正式版與Forever上使用現代名條、中等尺寸與相同條形尺寸。公會名稱與頭銜也會影響世界中的名稱。可在暴雪按鍵設定的MSUF Suite下綁定「切換友方NPC名條」。匯入保護會在匯入完整Suite設定檔時保留目前名條；單獨匯入名條仍會取代其設定。")
