T("Observed enemies adds up the enemy forces of the living enemies in combat that you see as a nameplate or target, and the total they would bring. Enemies that give no forces count as zero; while the client keeps a value hidden, the line shows -- instead of a guess. Enemies out of sight are not counted.", "已觀察的敵人會累加你透過名條或目標看到、處於戰鬥中的存活敵人的敵方部隊進度，並顯示它們將帶來的總計。不提供進度的敵人計為零；用戶端隱藏某個數值時，該行顯示 -- 而非估算。視野外的敵人不計入。")
