T("One combined bag with a clear Suite background and item levels on equipment. Keep Blizzard's own item grid, or choose a Suite view with pages, bag groups or categories. Using and sorting items stays Blizzard's.", "一個合併背包，具有清晰的Suite背景，並在裝備上顯示物品等級。可保留暴雪原生的物品格線，或選擇具有分頁、依背包分組或分類的Suite檢視。物品使用與整理仍由暴雪處理。")
