T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "只會開啟啟用此功能後新取得的容器。戰鬥結束後一次開啟一個；按住 Shift，或拾取視窗或會改變物品使用含義的視窗（商人、銀行、公會銀行、郵件、交易、拍賣場、拆解機、寶石插槽、升級等）開啟時，容器留給你手動處理。戰隊容器預設不開啟，除非你允許；先前已使用此功能的設定檔會繼續開啟它們。敦敦裂片達到上限時，可以暫緩開啟至暗之夜工匠報酬。")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "僅在進行中的探究且脫離戰鬥時：如果玩家選擇介面恰好只有一個可用法術選項、一個按鈕且無須確認，MSUF 才會選擇一次。其他選擇仍須手動處理。")
