T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "開啟物品升級商人視窗時，以上次使用的分頁開啟你的角色視窗。只會關閉由此功能開啟的視窗；戰鬥中的開啟或關閉會等到戰鬥結束。")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "可選用暴雪原有的聊天、地圖、聲音，以及低生命值或其他畫面閃爍設定。關閉單一選項或整個功能時，MSUF 會恢復原值；功能運作期間你在暴雪設定中手動修改的值仍會保留。")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "選用的裝飾圖與間距控制。使用MSUF編輯模式進行定位、微調、重置、復原與重做。")
