T("Remembers your characters that you visit while this helper is on and lists them beside the mail window. Click a name to fill the recipient, right-click to hide or restore it, and search by name. Only characters on your current or connected realms are listed. Sending stays manual.", "記錄啟用此輔助功能期間登入過的角色，並顯示在郵件視窗旁。點擊姓名可填寫收件人，右鍵可隱藏或恢復，並支援依名稱搜尋。僅列出目前伺服器或相連伺服器的角色。傳送仍需手動。")
