T("Reminders appear only outside combat. The advance setting also shows active buffs, food and weapon enchants when their remaining time reaches the chosen number of minutes; 0 shows only missing effects. A single scheduled wakeup handles the next threshold. Reminders hide in arenas and battlegrounds, where aura data can be restricted.", "提醒只在非戰鬥時出現。提前提醒設定也會在作用中的增益、食物與武器附魔剩餘時間達到所選分鐘數時顯示；0只顯示缺少的效果。單一排程喚醒會處理下一個門檻。提醒在競技場與戰場中隱藏，因為那裡的光環資料可能受限。")
