T("Replaces the merchant's pages with one list; scroll it with the mouse wheel or the bar. Right-click buys, left-click picks an item up and Shift-click asks for a quantity; linking and previewing work as usual. Purchases paid with currencies or items, or costing at least 150 gold, ask for confirmation first. The buyback tab keeps Blizzard's layout. Drop or click an item from your bags onto the list to sell it; one you can still refund asks whether to refund it.", "用一個清單取代商人的分頁；可用滑鼠滾輪或捲軸捲動。右鍵購買，左鍵拿起物品，Shift+點擊詢問數量；連結與預覽照常可用。使用貨幣或物品支付，或價格至少150金幣的購買會先要求確認。買回分頁維持暴雪的版面。將背包中的物品拖放或點擊到清單上即可出售；仍可退款的物品會詢問是否退款。")
