T("Reports the first observed death of each group member during combat. Local chat, a screen notice and a sound can be selected separately. Simultaneous deaths share one sound. Optionally include your own death. The listener is active only while you are grouped and in combat.", "通報戰鬥中首次觀察到的各隊員死亡。可分別選擇本機聊天、螢幕提示與音效。同時發生的死亡僅播放一次音效，也可包含自己的死亡。僅在組隊且處於戰鬥時偵測。")
