T("Restores this bar's default spells and buffs for your specialization. Other bars and specializations stay as they are. You can undo it.", "還原此條在你專精中的預設法術與增益。其他條與專精保持不變。你可以復原此操作。")
T("Restyles Blizzard's own buff and debuff buttons beside the minimap: icon size, icons per row, spacing, outline, text and where the block sits. Blizzard still owns the auras, their tooltips and right-click cancelling. The position and the debuff row offset are set here, not in Edit Mode. Each row's icon skin is chosen on the Icon Skins page.", "調整小地圖旁暴雪增益和減益按鈕的圖示大小、每行數量、間距、輪廓、文字和位置。光環、提示及右鍵取消仍由暴雪管理。位置和減益行偏移在此設定，不在編輯模式中設定。各行的圖示外觀在圖示外觀頁面選擇。")
T("Result", "結果")
