T("Resurrection offers", "復活請求")
T("Retail Druids only. Every incoming whisper in combat is a possible Innervate cue; message text cannot be inspected reliably during chat lockdown. The alert waits for a publicly known Innervate cooldown, or shows a generic cue when readiness is unavailable. A preferred target can be outlined on an MSUF group frame resolved outside combat. MSUF Edit Mode previews the alert and edits its position and size.", "僅限正式版德魯伊。戰鬥中收到的每則密語都可能是啟動請求；聊天鎖定期間無法可靠檢查訊息內容。提醒會等待公開可知的啟動冷卻結束，若無法得知是否就緒則顯示一般提示。偏好目標可在非戰鬥時解析的MSUF隊伍框架上加上外框。MSUF編輯模式可預覽提醒並編輯其位置與大小。")
T("Retail only. Shows while Skyriding is available, or only in flight if selected. Choose bars or Blizzard Vigor gems; gem scale and a refill sound are optional. Separate bar heights, Surge icon size and speed-value offsets are under Text and bars. MSUF Edit Mode previews the HUD. Unknown charge values display as dashes.", "僅限 Retail。在御空術可用時顯示，也可選擇僅飛行時顯示。可選進度條或暴雪活力寶石，寶石縮放與恢復音效可選。獨立條高度、奔湧圖示大小與速度數值偏移位於「文字與進度條」。MSUF 編輯模式可預覽 HUD。未知充能數值顯示為橫線。")
