T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "以文字、圖示或兩者顯示天氣。可選擇暴雪圖示或 Forever 原創圖案。僅顯示圖示時，滑鼠提示仍會顯示天氣名稱。")
T("Show weekly reward item levels", "顯示每週獎勵物品等級")
