T("Show windows", "顯示視窗")
T("Show your Bloodlust exhaustion or ready state while grouped.", "組隊時顯示自己受到嗜血類效果後的疲勞狀態，或顯示可用狀態。")
T("Show your owned item count, including bank and Warband bank, on item tooltips.", "在物品工具提示上顯示您擁有的物品數量，包括銀行和戰團銀行。")
T("Show your selected loot specialization in the Great Vault window.", "在宏偉寶庫視窗中顯示你選擇的拾取專精。")
T("Show zone", "顯示區域")
T("Show, hide and customize Blizzard's player buff and debuff bars.", "顯示、隱藏及自訂暴雪玩家增益與減益列。")
T("Shown value", "顯示的數值")
T("Shown windows: %d. Raise the number of windows to show this one.", "顯示中的視窗：%d。提高視窗數量即可顯示此視窗。")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "在進行中的傳奇+或團隊首領戰中顯示暴雪的共用戰鬥復活次數。圖示使用暴雪的冷卻顯示倒數下一次充能。無法取得共用次數時隱藏。MSUF編輯模式可預覽顯示並編輯X、Y、寬度、高度與縮放。")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "根據你已知法術的遊戲射程判定，顯示與目前目標的大致距離；數值包含目標的受擊範圍，顯示短橫表示沒有已知法術能夠判斷。用 {range} 和 {unit} 撰寫文字。估算值可以放在目標框架下方（框架移動時隨之移動），也可以放在螢幕任意位置；MSUF 編輯模式可移動這兩種位置。")
T("Shows each ready interrupt with the bar's glow style while the target's cast can be interrupted. Requires per-interrupt readiness from MSUF.", "目標的施法可被中斷時，使用冷卻列的發光樣式顯示每個已就緒的中斷技能。需要 MSUF 提供各個中斷技能的就緒資訊。")
T("Shows incoming damage and healing for you or your vehicle. Blizzard's own combat text is hidden while enabled and restored when disabled. Move the display in MSUF Edit Mode. During heavy bursts the oldest of the visible messages is replaced. The game may keep amounts private, so messages are never combined or filtered by their value.", "顯示你或載具受到的傷害與治療。啟用時隱藏暴雪自身戰鬥文字，停用後恢復。可在 MSUF 編輯模式中移動顯示位置。訊息密集時替換最早的可見訊息。遊戲可能隱藏數值，因此不會合併訊息或依數值篩選。")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "暴雪載入物品資料後，在商人的裝備上顯示物品等級。購回物品與沒有物品等級的物品保持不變。")
T("Shows the active potion buff. Instant healing and mana potions do not leave a buff.", "顯示目前生效的藥水增益。瞬間恢復生命值和法力的藥水不會留下增益。")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "開啟宏偉寶庫時顯示目前的拾取專精。視窗開啟期間變更拾取專精時會更新。")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "非戰鬥時，若已裝備物品的最低耐久度低於你選擇的門檻則顯示。即使裝備已修理，MSUF編輯模式也會顯示範例。其彈出視窗可編輯X、Y、寬度、高度與縮放。")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "當物品滑鼠提示提供公開物品 ID 時，顯示你擁有的數量，包括銀行與戰隊銀行。可選擇依存放位置分別顯示；數量為零的項目會省略。")
T("Shows the share of the keystone's enemy forces that an enemy gives, while a Mythic+ keystone is running and Blizzard shows no such line itself.", "在傳奇鑰石挑戰期間，若暴雪未自行顯示該資訊，則顯示此敵人貢獻的敵方部隊比例。")
T("Shows the spell's icon in the middle of the screen when its cooldown ends, even while this bar is hidden. Its size, place and time are in General.", "此法術冷卻結束時，在螢幕中央顯示其圖示，即使此條列已隱藏。大小、位置和時間在「一般」中設定。")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "在角色模型上顯示裝備的總耐久度，並依兩個偏移移動，同時裁切角色面板和觀察視窗中裝備欄圖示的邊緣。")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "暴雪顯示個人物品拾取提示時，額外顯示最多三則簡潔提示。可依最低品質、坐騎或寵物物品，以及最多 100 個物品 ID 篩選。暴雪原有提示仍會顯示；沒有拾取提示的普通背包物品不包含在內。")
T("Shows whichever haste buff is active, from any source: Bloodlust, Heroism, Time Warp, Primal Rage, Fury of the Aspects and similar.", "顯示任何來源目前生效的加速增益：嗜血、英勇、時間扭曲、原始狂怒、守護巨龍之怒等。")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "就位確認、地城排隊配對成功或進入副本時，顯示目前天賦配置與拾取專精。不會自動更改天賦或拾取專精。")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "顯示最近成功施放的法術。標準列包含圖示、名稱和標記；「僅圖示」預設則是精簡的直排圖示。顯示寬度只影響標準列；圖示預設的寬度由列高決定。可在 MSUF 編輯模式中設定位置和錨點，並查看範例動作。關閉後不再監聽法術事件。用戶端未公開詳細資料的法術無法顯示。")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "組隊時顯示你自身的嗜血疲勞狀態，也可選擇顯示可用狀態。相關玩家光環變化時會更新；可在 MSUF 編輯模式中移動並預覽疲勞狀態。")
