T("Silences the game sound files whose IDs you list, such as a mount or summon sound; up to 200. MSUF mutes exactly the files listed here and plays them again when you remove an ID or turn this helper off, and it leaves files muted by other addons alone. Muting works whether or not volume profiles are applied.", "靜音清單中指定 ID 的遊戲音效檔案，例如坐騎或召喚音效，最多 200 個。MSUF 只靜音所列檔案，移除 ID 或關閉輔助功能後恢復播放，並保留其他插件設定的靜音狀態。無論是否套用音量設定檔，此功能都有效。")
T("Silences these game sound files, such as a mount or summon sound, while this helper is on. Remove an ID to hear that sound again.", "啟用此輔助功能期間，靜音這些遊戲音效檔案，例如坐騎或召喚音效。移除 ID 即可恢復該音效。")
