T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. The bank views have the same smart search, free slot count and collapsible category headers. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "使用銀行視窗下方按鈕切換原生分頁、合併銀行、合併戰隊銀行和共用分類。共用分類包含可存取的角色與戰隊分頁。「管理銀行分頁」返回暴雪的購買、存入與分頁設定。銀行檢視同樣支援智慧搜尋、空格統計和可摺疊分類標題。每格保留原有物品操作，銀行堆疊不會合併；點擊戰隊物品會先切換至暴雪的戰隊銀行分頁，可退款物品存入戰隊銀行前會請求確認。")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "在此分別開啟或關閉快捷列。重新開啟時會恢復先前的顯示模式。選擇版面即可調整上方選取的快捷列。")
T("Switch on the first option, then keep or drop the reminders you want. A reminder shows only when your character knows its spell. Stances, auras, shields, Shadowform and weapon or shield imbues show while they are missing. Buffs you put on an ally (Source of Magic, Blistering Scales, Earth Shield, Symbiotic Relationship) show while your buff is on nobody in the group; target an ally and click the icon to cast it. Right-click or middle-click any reminder to hide it until you reload the UI.", "啟用第一個選項，再保留或關閉所需提醒。只有角色已學會相應法術時才會顯示提醒。姿態、光環、護盾、暗影形態及武器或盾牌灌注會在缺少時顯示。對盟友施加的增益（魔力之源、炙熱鱗片、大地之盾、共生關係）會在隊伍中無人擁有你的該增益時顯示；選取盟友並點擊圖示即可施放。右鍵或中鍵點擊任意提醒可將其隱藏，直到重新載入介面。")
T("Switch the whole Skinning module here, or adjust Blizzard and Suite windows separately below.", "在此切換整個美化模組，或在下方分別調整暴雪與Suite視窗。")
