T("Ten action bars plus stance and pet bars with free layout, paging, visibility rules and button styling. Key bindings keep using Blizzard's commands.", "十條快捷列加上姿態列與寵物快捷列，可自由配置版面、換頁、可見性規則與按鈕風格。按鍵綁定仍使用暴雪的指令。")
