T("Textures use the window and header colors and opacity. Turn the texture switch off to return to a flat color.", "材質使用視窗與標題列的顏色及不透明度。關閉材質開關即可恢復純色。")
T("That bar shows buffs.", "該條顯示增益。")
T("That bar shows cooldowns.", "該條顯示冷卻。")
T("That changed since, so it cannot be undone.", "之後已有變更，因此無法復原。")
T("That chat channel is not available right now.", "該聊天頻道目前無法使用。")
T("That did not work.", "操作未成功。")
