T("The Durability, FPS and Latency places, and FPS / latency, take the warning color at these limits.", "耐久度、畫面更新率、延遲資訊區塊以及「畫面更新率 / 延遲」會在達到這些門檻時採用警告顏色。")
T("The Glass material with MSUF Forever graphite, ivory and muted-gold colors.", "玻璃質感，搭配MSUF Forever的石墨色、象牙色與柔和金色。")
T("The Great Vault is available only in Retail", "宏偉寶庫僅適用於正式版")
T("The Mapko skin for Blizzard nameplates. Blizzard keeps health, threat, casts, auras, selection and click handling.", "用於暴雪名條的Mapko外觀。生命值、威脅、施法、光環、選取與點擊處理仍由暴雪管理。")
T("The Suite Cooldown manager page (CDM) shows Blizzard's tracked cooldowns and buffs as bars you arrange and style freely.", "Suite 的冷卻管理器（CDM）頁面將暴雪追蹤的冷卻時間與增益效果顯示為可自由排列及設定樣式的計時條。")
T("The Suite Minimap page styles the minimap itself: size, shape, border, zoom, buttons and info texts. MSUF's own minimap icon is under Miscellaneous.", "Suite 的小地圖頁面可設定小地圖本身的大小、形狀、邊框、縮放、按鈕及資訊文字。MSUF 自身的小地圖圖示位於「其他」中。")
T("The Suite Nameplates page styles Blizzard's enemy and friendly nameplates. MSUF's aura filters only decide whether nameplate-only auras show on MSUF frames.", "Suite 的名條頁面可設定暴雪敵方與友方名條的樣式。MSUF 的光環篩選器僅決定是否在 MSUF 框架上顯示僅限名條的光環。")
T("The Suite draws its own tracker and hides Blizzard's while it runs. Entries are sorted into groups: the focused quest, campaign and important quests, quests ready to hand in, regular quests, world quests, nearby bonus objectives, scenario and delve steps, zone event progress, tracked achievements and collectibles and, on Retail, tracked recipes, Traveler's Log activities and Housing endeavors. In a raid it can hide completely, only while a boss is engaged, or pause the regular list during any raid fight; the encounter view keeps running then. Quest symbols come as Suite letters or as Blizzard's icons, and the heading line can be switched off. The key binding Use tracked quest item uses the focused quest's item, else the first usable one, and picks a new item only outside combat. Left-click a group name to fold it or a quest to open its log entry; right-click for more actions.", "Suite 使用自己的追蹤器，執行時隱藏暴雪追蹤器。內容依焦點任務、戰役和重要任務、可交付任務、一般任務、世界任務、附近獎勵目標、事件與探究步驟、區域事件進度、已追蹤成就與收藏品分組；在正式服還包括追蹤的配方、旅人日誌活動及家宅活動。團隊中可完全隱藏、僅首領交戰時隱藏，或在任何團隊戰鬥期間暫停一般清單；戰鬥檢視仍繼續執行。任務標記可使用 Suite 字母或暴雪圖示，標題行可關閉。「使用追蹤任務物品」快捷鍵會使用焦點任務物品，否則使用首個可用物品；僅在非戰鬥狀態選擇新物品。左鍵點擊組名可摺疊，點擊任務可開啟日誌；右鍵顯示更多操作。")
T("The Suite frames Blizzard's original Micro Buttons. Their artwork, clicks, tooltips, enabled states and notifications stay native. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "Suite為暴雪原有的微型選單按鈕加上外框。其圖案、點擊、滑鼠提示、啟用狀態與通知維持原生。佇列與FPS指示器停留在暴雪編輯模式中的位置。不會執行任何週期性MSKIN更新。")
T("The Suite look gives Blizzard's dialogs a dark panel, and the Suite font sets their text font and size; each works alone, and without them dialogs keep Blizzard's look and fonts. A minimum height makes short dialogs taller once Blizzard has sized them; 0 keeps Blizzard's height. A custom position moves the first dialog and the ones Blizzard stacks below it; place it and set the height in MSUF Edit Mode.", "Suite外觀為暴雪對話框提供深色面板，Suite字型設定其文字的字型和大小；兩者都可單獨使用，沒有它們時對話框保持暴雪的外觀和字型。最小高度會在暴雪確定大小後讓較短的對話框變高；0保留暴雪的高度。自訂位置會移動第一個對話框及暴雪在其下方堆疊的對話框；在MSUF編輯模式中放置它並設定高度。")
T("The Suite skin engine is unavailable.", "無法使用Suite美化引擎。")
T("The WoW macro changed; import it again before replacing it", "WoW巨集已變更，請重新匯入後再取代")
T("The WoW macro is no longer available", "此WoW巨集已無法使用")
T("The action-bar glow also requires this buff on you. Clear the field to use only the original buff or stack condition.", "快捷列發光還要求你身上有此增益。清空此欄位可僅使用原有增益或層數條件。")
T("The bank selection changed. Review the preview again.", "銀行選擇已變更。請重新檢查預覽。")
T("The chosen font could not be applied.", "無法套用所選字型。")
T("The chosen font was not found, so Blizzard text keeps its own font.", "找不到所選字型，暴雪文字將保留原字型。")
T("The chosen profile supplies all settings. Toggle which Suite modules are enabled in it.", "所選設定檔提供所有設定。可切換其中啟用哪些Suite模組。")
T("The class buff is included only when your character knows it. Enter self-buff spell IDs separated by spaces or commas. For a consumable, enter item ID:aura ID; separate pairs with commas. Up to 12 total reminders are shown. Weapon enchant items use the main-hand or off-hand enchant state.", "只有在你的角色已學會時才會包含職業增益。輸入自身增益法術ID，以空格或逗號分隔。消耗品請輸入物品ID:光環ID；每組之間以逗號分隔。最多顯示12個提醒。武器附魔物品會使用主手或副手的附魔狀態。")
T("The combined bag and reagent bag use a Suite panel with a distinct header, border, and accent line. Set background opacity to 0 for a transparent window; item slots stay visible.", "合併背包與材料背包使用Suite面板，具有獨特的標題、邊框與強調線。將背景不透明度設為0即可讓視窗透明；物品欄位仍會顯示。")
T("The combined bag setting is protected on this client", "此用戶端的合併背包設定受到保護")
T("The configuration cannot be opened during combat.", "戰鬥中無法開啟設定。")
T("The cooldown catalog is not available yet. Log in on this character and specialization, then open this page.", "冷卻目錄尚無法使用。請使用此角色和專精登入，然後開啟此頁面。")
T("The cooldown manager is not loaded.", "冷卻管理員未載入。")
T("The cooldown manager needs an update. Reload the interface.", "冷卻管理員需要更新。請重新載入介面。")
T("The cooldown manager was reset: settings, spell lists and spell options.", "冷卻管理員已重置：設定、法術清單與法術選項。")
T("The countdown turns to the warning color below this many seconds. All bars: the Text section's setting.", "倒數低於此秒數時會變為警告顏色。所有條：採用文字區段的設定。")
T("The dark sweep over the icon while it counts down.", "倒數時覆蓋在圖示上的深色轉圈。")
T("The default font follows MSUF Fonts while the default size follows Blizzard's chat size. Choose Blizzard chat font to keep its own face. Slug has no shadow.", "預設字型跟隨MSUF字型，預設大小則跟隨暴雪聊天大小。選擇「暴雪聊天字型」可保留其原本字型。Slug沒有陰影。")
T("The detailed character panel and stats are available only in Retail. WoW Forever keeps its own character layout.", "詳細角色面板與屬性僅在正式服可用。WoW Forever 保留自己的角色配置。")
T("The detailed character panel is available only in Retail.", "詳細角色面板僅在正式服可用。")
T("The dungeon's timer", "地城計時")
T("The engine remains dormant until a lifecycle event or an explicit user action requires work.", "在生命週期事件或使用者明確操作需要處理之前，引擎保持休眠。")
T("The game could not use the chosen font, so Blizzard text keeps its own font.", "遊戲無法使用所選字型，暴雪文字將保留原字型。")
T("The game has not sent the current season yet; until then every learned portal is listed.", "遊戲尚未傳送目前賽季；在此之前會顯示所有已學會的傳送。")
T("The global cooldown can leave the ring for a fixed circle of its own size and opacity, shown next to casts. Place it in MSUF Edit Mode; its button there works while this choice is on.", "共用冷卻可以離開圓環，顯示在一個有自己大小和不透明度的固定圓圈中，並與施法同時顯示。在 MSUF 編輯模式中放置它；該選項開啟時，那裡的按鈕才可用。")
T("The global name of a frame, for example ChatFrame1. The bar follows its place and size, never anchored to it. Until the frame exists, the bar stays put.", "框架的全域名稱，例如 ChatFrame1。條列會跟隨其位置和大小，但不直接錨定至該框架。框架出現前，條列保持原位。")
T("The header shows the meter and fight. Its buttons change the meter and fight directly in the window.", "標題列顯示統計類型與戰鬥。其按鈕可直接在視窗中切換統計類型與戰鬥。")
T("The item changed. Review the preview again.", "物品已變更。請重新檢查預覽。")
T("The keystone notice remains local. The optional group announcement forwards only Blizzard's confirmed reset message immediately after your own reset request, while you are group leader. Failed attempts and resets by other players are not announced.", "鑰石提示仍僅在本機顯示。可選的隊伍通報僅在你擔任隊長並親自請求重置後，立即轉發暴雪確認的重置訊息。失敗的嘗試及其他玩家發起的重置不會通報。")
T("The level number takes the color Blizzard gives it on the target frame. Units you cannot attack keep white.", "等級數字採用暴雪目標框架的顏色。無法攻擊的單位保持白色。")
T("The list of kept buttons is full.", "保留按鈕清單已滿。")
T("The macro draft is no longer available", "巨集草稿已無法使用")
T("The macro exceeds the 255-character limit", "巨集超出 255 個字元的限制")
T("The macro library is full", "巨集庫已滿")
T("The map grows or shrinks to the chosen width and height while the pointer is over it, then returns to its normal size. A circular map keeps its height equal to its width.", "滑鼠指標位於地圖上時，地圖會放大或縮小到所選的寬度與高度，移開後恢復正常大小。圓形地圖的高度與寬度保持相同。")
T("The merchant's offers changed; nothing was bought.", "商人的商品已變更，未購買任何物品。")
T("The merchant's whole stock in one scrolling list with prices, quality colors and item levels.", "以一個可捲動清單顯示商人的全部商品，包含價格、品質顏色與物品等級。")
T("The minutes below", "下方的分鐘數")
T("The mouse wheel zooms the map. Middle-click runs the chosen action; left and right clicks keep working as usual.", "滑鼠滾輪可縮放地圖。中鍵執行所選動作；左鍵與右鍵維持一般功能。")
T("The native input box keeps autocomplete, links and chat commands.", "原生輸入框保留自動完成、連結與聊天指令。")
T("The normal warning time", "正常提醒時間")
T("The optional glyph layer changes appearance while Blizzard keeps clicks, tooltips, enabled states and notifications. Queue and FPS indicators stay at Blizzard's Edit Mode position. No recurring MSKIN update runs.", "選用的符號層改變外觀，點擊、滑鼠提示、啟用狀態與通知仍由暴雪保留。佇列與FPS指示器停留在暴雪編輯模式中的位置。不會執行任何週期性MSKIN更新。")
T("The options module could not be loaded: %s", "無法載入選項模組：%s")
T("The options module did not finish initializing.", "選項模組未完成初始化。")
T("The party table grows in steps: characters with build and score, then the combat figures of Blizzard's damage meter, then the loot seen in chat. Each character keeps its latest runs; open the newest here or with /msufruns and step through older ones. Deleting a run asks for a second click. The card can wait until you close the chest's loot window.", "隊伍表格依階段擴充：帶有配置與評分的角色，接著是暴雪傷害統計的戰鬥數據，然後是在聊天中看到的戰利品。每個角色保存自己最近的挑戰；在此處或使用 /msufruns 開啟最新的一次，再翻看較早的紀錄。刪除挑戰需要再點擊一次。卡片可以等到你關閉寶箱的戰利品視窗後再顯示。")
T("The preview and every section below edit this bar. Shared custom groups start with a separate list for explicit spell, aura and item IDs; disabling sharing restores the existing per-specialization list.", "預覽與下方所有區段都編輯此列。共用自訂分組使用獨立的明確法術、光環與物品ID清單；關閉共用後會恢復現有的各專精清單。")
