T("Timestamps use Blizzard's chat setting across all chat windows. Copy is off by default; when enabled, move its button with X/Y, choose a message, then press Ctrl+C. The displayed timestamp is included when timestamps are on. The message tools leave the Combat Log alone (its own settings can add a timestamp to every line); its lines still wake the idle fade. Saved history belongs to this character.", "時間戳記在所有聊天視窗中使用暴雪的聊天設定。複製功能預設為關閉；啟用後，可用X/Y移動其按鈕，選擇一則訊息，然後按Ctrl+C。開啟時間戳記時，會一併包含顯示的時間戳記。訊息工具不會處理戰鬥記錄（它自己的設定可以為每一行加上時間戳記）；戰鬥記錄的新行仍會喚醒閒置淡出。儲存的歷史記錄屬於目前角色。")
