T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "輸入 /keys 或 /msufkeys 查看自己目前的鑰石。在指令後加上 party、raid 或 instance 可分享到對應頻道。/keys group 會向同樣執行此 Suite 功能的隊友請求鑰石資訊。僅在其他插件未占用 /keys 時才啟用此別名。在地城和團隊副本中暴雪會禁止插件傳送聊天訊息，此時鑰石只會顯示給你自己。")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. The guild chat in the Guild & Communities window can be covered as well; other communities stay visible. Reveal the chat again with the click chosen here. Messages keep arriving underneath.", "輸入 /msufguildprivacy，或使用主聊天視窗上方的小型 ON/OFF 按鈕。只要聊天視窗包含公會或幹部頻道，即使混有其他頻道，也會遮住整個視窗。「公會與社群」視窗中的公會聊天也可以遮住，其他社群保持可見。使用此處選擇的點擊方式即可重新顯示聊天；訊息仍會在遮罩下持續接收。")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "輸入 /msufraid 展開暴雪團隊管理器，輸入 /msufpull [1-60] 使用其內建倒數，或輸入 /msufmark tank 或 /msufmark healer 為一名身分明確的隊員加上標記。自動標記僅在五人隊伍中恰好只有一名坦克或治療者、且你是隊長或助理時生效。現有及已占用的標記不會被覆蓋。戰鬥、首領戰和鑰石期間暴雪限制倒數、標記和準備確認，這些操作會等待；自動標記會在之後再次嘗試。")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "輸入 /way x y 可在目前地圖設定路徑點，也可輸入 /way mapID x y 指定地圖。/msufway 始終可用；只有其他插件未使用 /way 時，才會啟用這個簡寫指令。")
