T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "顯示哪些數字、哪個顯示在上層，以及它們的大小與位置。個別法術可以不同：在預覽中點擊它們。下方的字型設定套用到每一條；Slug沒有陰影。")
T("Which units get nameplates and how plates share space.", "哪些單位顯示名條，以及名條如何分配空間。")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "啟用資料文字與此選項後，MSUF會在登入及金幣變動時記錄此角色的金幣。將游標停在「金幣」或「本次登入金幣」資料文字上，可查看最後已知的帳號總額及最多八個其他角色。不會執行背景掃描。")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "資訊文字啟用時，隱藏暴雪的行囊與背包欄位。點擊「背包空間」資訊文字可開啟原生背包。關閉此選項即可恢復暴雪按鈕。")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "鑰石進行時，每個已擊敗的首領會顯示你領先或落後多少：對比你在該首領上的最佳時間，或對比你最快完成挑戰中的首領時間，可選目前鑰石等級或任意等級。只計入此角色完成的挑戰。開啟目標時間後，仍存活的首領會顯示需要超越的時間。")
T("While the buff of this item's use lasts, the icon shows its duration and stacks instead of the cooldown.", "此物品使用後的增益持續期間，圖示顯示增益持續時間與層數，而非冷卻時間。")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "此法術的增益持續期間，圖示會顯示其持續時間與堆疊，而非冷卻。")
T("While this is on, move the window in MSUF Edit Mode or with the two positions below. While it is off, Blizzard's Edit Mode places it.", "啟用時，可在 MSUF 編輯模式或透過下方兩個位置設定移動視窗。關閉時，由暴雪編輯模式負責定位。")
