T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "僅限 WoW Forever。依暴雪的威脅資料由高到低列出隊伍對所關注敵人的威脅；友方目標則使用其敵人。遊戲隱藏的數值不會顯示。成員多於列數時，在視窗上滾動滑鼠滾輪。紅色標記表示你會拉到仇恨的位置，這與追平坦克的位置不同。計量器每秒最多重繪五次，不讀取戰鬥紀錄。")
